2	import { join, dirname } from "node:path";
3	import { fileURLToPath } from "node:url";
4	import { createAuthAnalyticsEvent } from "./analytics/events.js";
5	import { analytics } from "./analytics/posthog.js";
6	import { runAuthCommand, type AuthSuccess } from "./auth.js";
7	import { findGame, isPlayable, REGISTRY } from "./games/registry.js";
8	import { launchOverlay as showOverlay } from "../scripts/overlay.js";
9	import { detectInstallContext, writeInstallContext } from "../scripts/plugin-update.js";
10	
11	const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
12	
13	function captureAuthSuccess(result: AuthSuccess): void {
14	  if (result.userId) analytics.setDistinctId(result.userId);
15	  analytics.capture(createAuthAnalyticsEvent(result));
16	}
17	
18	function printUsage(): void {
19	  const ids = REGISTRY.filter(isPlayable).map((entry) => entry.id).join(", ");
20	  console.log("usage: gamepigeon [game]");
21	  console.log("       gamepigeon auth [signup|login|status|logout]");
22	  console.log("       gamepigeon install [--codex|--claude|--opencode|--hermes|--openclaw|--antigravity|--all]");
23	  console.log("       gamepigeon export [--input <file-or-directory>]... [--output <directory>] [--include-noops]");
24	  console.log("");
25	  console.log("With no argument, opens the arcade overlay menu.");
26	  console.log(`Available games: ${ids}`);
27	}
28	
29	async function installAdapters(target?: string): Promise<void> {
30	  const proc = Bun.spawn(["bash", join(ROOT, "scripts/install-adapters.sh"), target ?? "--all"], {
31	    cwd: ROOT,
32	    env: { ...process.env, GAMEPIGEON_WORKSPACE_DIR: process.cwd() },
33	    stdin: "ignore",
34	    stdout: "inherit",
35	    stderr: "inherit",
36	  });
37	  await proc.exited;
38	  if (proc.exitCode !== 0) process.exit(proc.exitCode ?? 1);
39	  // The adapters now point at *this* checkout. Record it immediately so an
40	  // in-overlay update (which runs this command from a fresh npx checkout) can
41	  // reopen the new launcher instead of the one it just replaced.
42	  const harness = target?.startsWith("--") ? target.slice(2) : undefined;
43	  writeInstallContext(detectInstallContext(ROOT, {
44	    ...process.env,
45	    ...(harness && harness !== "all" ? { GAMEPIGEON_HARNESS: harness } : {}),
46	  }));
47	}
48	
49	async function launchOverlay(gameId?: string): Promise<void> {
50	  await showOverlay("show", ROOT, { gameId });
51	}
52	
53	async function exportBc(args: string[]): Promise<void> {
54	  // Relative --input/--output paths belong to whoever ran the command, not to the
55	  // install directory: a globally installed package root is often unwritable, and a
56	  // dataset written there would be lost on the next upgrade.
57	  const proc = Bun.spawn([process.execPath, join(ROOT, "scripts/export-bc.ts"), ...args], {
58	    cwd: process.cwd(),
59	    stdin: "ignore",
60	    stdout: "inherit",
61	    stderr: "inherit",
62	  });
63	  await proc.exited;
64	  if (proc.exitCode !== 0) process.exit(proc.exitCode ?? 1);
65	}
66	
67	async function main(): Promise<void> {
68	  let arg = process.argv[2];
69	  if (arg === "--game") arg = process.argv[3] ?? "";
70	  if (arg === "--help" || arg === "-h") {
71	    printUsage();
72	    return;
73	  }
74	  if (arg === "auth") {
75	    try {
76	      const result = await runAuthCommand(process.argv[3]);
77	      if (result) captureAuthSuccess(result);
78	    } finally {
79	      await analytics.shutdown();
80	    }
81	    return;
82	  }
83	  if (arg === "install") {
84	    await installAdapters(process.argv[3]);
85	    return;
86	  }
87	  if (arg === "export") {
88	    await exportBc(process.argv.slice(3));
89	    return;
90	  }
91	
92	  let gameId: string | undefined;
93	  if (arg !== undefined) {
94	    const entry = findGame(arg);
95	    if (!entry || !isPlayable(entry)) {
96	      const ids = REGISTRY.filter(isPlayable).map((entry) => entry.id).join(", ");
97	      console.error(`Unknown or unavailable game "${arg}". Available games: ${ids}`);
98	      process.exit(1);
99	    }
100	    gameId = entry.id;
101	  }
102	
103	  await launchOverlay(gameId);
104	}
105	
106	main().catch((error: unknown) => {
107	  console.error(error instanceof Error ? error.message : String(error));
108	  process.exit(1);
109	});
