/**
 * Reads one query value, treating a literal `?` like `&`: some hosted redirects
 * append `?token=...` onto a callback that already carried `?state=...`, leaving
 * `state=<nonce>?token=<value>` in a single pair. Values come back exactly as
 * they arrived — tokens round-trip through the listener verbatim.
 */
function queryParam(query: string, key: string): string | null {
  for (const pair of query.split(/[&?]/)) {
    const equals = pair.indexOf("=");
    if (equals === -1) continue;
    if (pair.slice(0, equals) === key) return pair.slice(equals + 1);
  }
  return null;
}

// Percent-decoding for human-readable query text (OAuth error descriptions).
function decodeQueryText(value: string): string {
  const spaced = value.replace(/\+/g, " ");
  try {
    return decodeURIComponent(spaced);
  } catch {
    return spaced;
  }
}

// Turns a failed handoff (`?error=...`) into a sentence worth showing. Capped
// because it lands in both the browser page and the terminal.
function callbackFailure(query: string): string | null {
  const error = queryParam(query, "error");
  if (!error) return null;
  if (error === "access_denied") return "Sign-in was cancelled before it finished.";
  const description = decodeQueryText(queryParam(query, "error_description") ?? "");
  const message = description || `The login page reported an error: ${decodeQueryText(error)}`;
  return message.slice(0, 200);
}

export interface OAuthCallbackServer {
  readonly port: number;
  ready: Promise<void>;
  token: Promise<string>;
  close(): void;
}

/**
 * Serves the loopback leg of a browser sign-in: the auth Worker sends the
 * signed-in browser to `http://127.0.0.1:<port>/auth/callback?...&token=...`,
 * and this listener turns that request into a resolved `token` plus a page the
 * user can close. `/auth/ping` answers the Worker's readiness probe.
 *
 * Returns synchronously, so the handle exists before the socket is bound; only
 * `ready` says binding finished and that `port` has its final value (the
 * requested port being taken costs one retry on an OS-assigned free port).
 *
 * `token` resolves with the raw, unverified query value. Unlike the overlay's
 * Rust listener (`tauri/src/main.rs`), which compares `state` against a nonce it
 * generated itself, this function is handed only a port — it has no nonce to
 * compare against, so `state` is accepted and ignored here. Checking the token
 * against the auth backend is `resolveUser`'s job, layered on top.
 */
export function startOAuthCallbackServer(port: number): OAuthCallbackServer {
  let settleReady!: () => void;
  let failReady!: (error: Error) => void;
  const ready = new Promise<void>((resolve, reject) => {
    settleReady = resolve;
    failReady = reject;
  });

  let settleToken!: (token: string) => void;
  let failToken!: (error: Error) => void;
  const token = new Promise<string>((resolve, reject) => {
    settleToken = resolve;
    failToken = reject;
  });
  // Marks `token` as handled: a caller that only drives the HTTP surface — a
  // test, or a command that gave up first — must not trip an unhandled
  // rejection when the browser reports a cancellation.
  void token.catch(() => {});

  const server = createServer((request, response) => {
    const target = request.url ?? "/";
    const separator = target.indexOf("?");
    const path = separator === -1 ? target : target.slice(0, separator);
    const query = separator === -1 ? "" : target.slice(separator + 1);

    const reply = (status: number, contentType: string, body: string): void => {
      response.writeHead(status, {
        "content-type": contentType,
        // Pages carry a session token in their URL — keep them out of caches
        // and out of the Referer sent to anything they link to.
        "cache-control": "no-store",
        "referrer-policy": "no-referrer",
        connection: "close",
      });
      response.end(body);
    };

    if (path === "/auth/ping") {
      reply(200, "text/plain; charset=utf-8", "ok");
      return;
    }
    if (path !== "/auth/callback") {
      reply(404, "text/plain; charset=utf-8", "not found");
      return;
    }
    // A login page that gave up hands back `error` instead of `token`; saying
    // why beats the generic "did not return a session token".
    const failure = callbackFailure(query);
    if (failure) {
      reply(400, "text/html; charset=utf-8", signInFailedPage(escapeHtml(failure)));
      failToken(new Error(failure));
      return;
    }
    const received = queryParam(query, "token");
    if (received) {
      reply(200, "text/html; charset=utf-8", signedInPage());
      settleToken(received);
      return;
    }
    const reason = "The login page came back without a session token.";
    reply(400, "text/html; charset=utf-8", signInFailedPage(escapeHtml(reason)));
    failToken(new Error(reason));
  });

  let boundPort = port;
  let retriedFreePort = false;
  server.on("error", (error: NodeJS.ErrnoException) => {
    if (!retriedFreePort && error.code === "EADDRINUSE") {
      retriedFreePort = true;
      server.listen(0, "127.0.0.1");
      return;
    }
    const failed = error instanceof Error ? error : new Error(String(error));
    failReady(failed);
    failToken(failed);
  });
  server.listen(port, "127.0.0.1", () => {
    const address = server.address();
    if (address && typeof address === "object") boundPort = (address as AddressInfo).port;
    settleReady();
  });

  return {
    get port(): number {
      return boundPort;
    },
    ready,
    token,
    close(): void {
      server.closeAllConnections?.();
      server.close();
    },
  };
}

function applescriptEscape(value: string): string {
  return value.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
}

/**
 * Arc (and Dia, same vendor) route links from other apps into a "Little Arc"
 * window, which drops the login page's redirect chain — the tab either never
 * appears or dies mid-handoff, so sign-in silently never completes. Mirrors
 * `is_arc_bundle` in `tauri/src/main.rs`.
 */
export function isArcBundle(bundleId: string): boolean {
  const id = bundleId.toLowerCase();
  return id === "company.thebrowser.browser" || id === "company.thebrowser.dia";
}

/**
 * Asks Arc for a real tab in a real window, which bypasses Little Arc entirely.
 * Mirrors `open_in_arc` in `tauri/src/main.rs`.
 */
export function arcTabScript(bundleId: string, url: string): string {
  return `tell application id "${applescriptEscape(bundleId)}"
    activate
    if (count of windows) is 0 then
        make new window
    end if
    tell front window to make new tab with properties {URL:"${applescriptEscape(url)}"}
end tell`;
}

/**
 * Runs an opener and reports whether it actually succeeded. Spawning alone
 * can't tell us that — `xdg-open` with no handler and `open` with a broken
 * default browser both fail *after* the spawn — so we wait for the exit status.
 */
function runOpener(command: string, args: string[]): boolean {
  try {
    return Bun.spawnSync([command, ...args], {
      stdin: "ignore",
      stdout: "ignore",
      stderr: "ignore",
    }).success;
  } catch {
    return false;
  }
}

/**
 * `defaults read` prints one dict per registered handler; the role and the
 * scheme are separate lines inside the same `{ ... }` block, so we scan block by
 * block for the one claiming `https`.
 */
function parseDefaultHttpsHandler(plist: string): string | null {
  for (const block of plist.split("{")) {
    if (!block.includes("LSHandlerURLScheme = https;")) continue;
    const line = block.split("\n").find((entry) => entry.trimStart().startsWith("LSHandlerRoleAll = "));
    if (!line) continue;
    const value = line.trim()
      .replace(/^LSHandlerRoleAll = /, "")
      .replace(/;$/, "")
      .replace(/^"|"$/g, "");
    if (value) return value;
  }
  return null;
}

/**
 * The bundle id macOS would hand an `https` URL to, read from LaunchServices.
 * Used only to detect Arc; any parse failure just means we take the ordinary
 * `open` path.
 */
function defaultHttpsHandler(): string | null {
  try {
    const result = Bun.spawnSync([
      "defaults",
      "read",
      "com.apple.LaunchServices/com.apple.launchservices.secure",
    ], { stdin: "ignore", stderr: "ignore" });
    if (!result.success) return null;
    return parseDefaultHttpsHandler(result.stdout.toString());
  } catch {
    return null;
  }
}

/**
 * Hands the sign-in URL to the user's browser. Returns false when every opener
 * we know about failed — the caller then leads with the printable link instead
 * of claiming a browser is opening.
 */
function openBrowser(url: string): boolean {
  if (process.platform === "darwin") {
    const bundleId = defaultHttpsHandler();
    if (bundleId && isArcBundle(bundleId) && runOpener("osascript", ["-e", arcTabScript(bundleId, url)])) {
      return true;
    }
    // Safari is the last resort: it is always present, so a broken or missing
    // default handler still gets the user to the login page.
    return runOpener("open", [url]) || runOpener("open", ["-a", "Safari", url]);
  }
  if (process.platform === "win32") {
    return runOpener("cmd", ["/c", "start", "", url])
      || runOpener("rundll32", ["url.dll,FileProtocolHandler", url]);
  }
  return runOpener("xdg-open", [url])
    || runOpener("gio", ["open", url])
    || runOpener("x-www-browser", [url]);
}

function requireOAuthProvider(value?: string): OAuthProvider {
  const provider = (value ?? "").toLowerCase();
  if ((oauthProviders as readonly string[]).includes(provider)) return provider as OAuthProvider;
  throw new Error(`usage: gamepigeon auth oauth [${oauthProviders.join("|")}]`);
}

/**
 * Browser sign-in: the Worker owns the provider round trip and hands the session
 * back to our loopback listener. Reported as `signed_in` even for a brand new
 * account, since the provider handoff does not say which one it was.
 */
async function signInWithOAuth(provider: OAuthProvider): Promise<AuthSuccess> {
  const authBaseUrl = requireAuthBaseUrl();
  const callback = startOAuthCallbackServer(defaultCallbackPort);
  let timeout: ReturnType<typeof setTimeout> | undefined;
  try {
    await callback.ready;
    // The nonce rides along so the Worker's token append has an existing query
    // to preserve, exactly as the hosted login page's redirect does.
    const next = `http://127.0.0.1:${callback.port}/auth/callback?state=${randomBytes(16).toString("hex")}`;
    const url = `${authBaseUrl}/cli/oauth?provider=${provider}&next=${encodeURIComponent(next)}`;
    const label = provider === "google" ? "Google" : "GitHub";
    console.log(
      openBrowser(url)
        ? `Opening your browser to finish signing in with ${label}...`
        : `Could not open your browser. Sign in with ${label} here:`,
    );
    console.log(`  ${url}`);

    const token = await Promise.race([
      callback.token,
      new Promise<never>((_resolve, reject) => {
        timeout = setTimeout(() => reject(new Error("Sign-in timed out. Try again.")), signInTimeoutMs);
      }),
    ]);
    const user = await resolveUser(token);
    saveSession(token, user);
    console.log(`Signed in as ${user.email}`);
    return { kind: "signed_in", method: provider, userId: user.id };
  } finally {
    if (timeout) clearTimeout(timeout);
    callback.close();
  }
}

export type { AuthUser, StoredSession };

