const CHECK_ICON =
  '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 6 9 17l-5-5"/></svg>';
const ALERT_ICON =
  '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 7.5v5.5"/><path d="M12 16.5h.01"/></svg>';

export function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

interface PageParts {
  tone: "ok" | "warn";
  title: string;
  lead: string;
  steps?: string[];
  hint?: string;
  head?: string;
  tail?: string;
}

/**
 * Renders one self-contained Tui page — no external CSS, fonts, or images.
 *
 * `lead`, `steps`, `hint`, `head`, and `tail` are trusted HTML so copy can carry
 * `<code>` spans; the title is escaped. Escape request-derived text at the call
 * site.
 */
function arcadePage({ tone, title, lead, steps = [], hint = "", head = "", tail = "" }: PageParts): string {
  const list = steps.length === 0
    ? ""
    : `<ul class="steps">${steps.map((step) => `<li>${step}</li>`).join("")}</ul>`;
  const hintHtml = hint ? `<p class="hint">${hint}</p>` : "";
  const titleText = escapeHtml(title);
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="robots" content="noindex">
<meta name="referrer" content="no-referrer">
<title>Tui — ${titleText}</title>
${head}<style>${STYLE}</style>
</head>
<body>
<main class="card" data-tone="${tone}">
<span class="badge">${tone === "ok" ? CHECK_ICON : ALERT_ICON}</span>
<p class="eyebrow">Tui</p>
<h1>${titleText}</h1>
<p class="lead">${lead}</p>
${list}
${hintHtml}
</main>
${tail}</body>
</html>`;
}

/**
 * Hands the browser session back to the CLI's loopback listener.
 *
 * The scripted redirect carries the target verbatim (a serialized URL never
 * contains a raw `<` or `"`, so it is inert inside a `<script>` element); the
 * `<meta http-equiv="refresh">` copy is HTML-escaped and exists for browsers
 * with scripting disabled.
 */
export function handoffPage(url: string): string {
  const escaped = escapeHtml(url);
  return arcadePage({
    tone: "ok",
    title: "Signing you in",
    lead: "Handing this session back to your terminal. This tab closes itself out of the way in a moment.",
    steps: [],
    hint: `Nothing happening? <a href="${escaped}">Continue to Tui</a>.`,
    head: `<meta http-equiv="refresh" content="0;url=${escaped}">\n`,
    // Kept last so the page has already painted if the redirect is slow.
    tail: `<script>location.replace("${url.replace(/\\/g, "\\\\").replace(/"/g, "%22").replace(/</g, "\\u003C")}")</script>\n`,
  });
}

/** The browser reached `/cli/handoff` without a session to hand back. */
export function signInRequiredPage(): string {
  return arcadePage({
    tone: "warn",
    title: "You're not signed in yet",
    lead: "This page hands an existing browser session back to Tui, and there is no session on this browser.",
    steps: [
      "Start the browser sign-in from your terminal with <code>gamepigeon auth oauth google</code> or <code>gamepigeon auth oauth github</code>.",
      "Finish the provider's consent screen; Tui picks the session up automatically.",
    ],
    hint: "Prefer a password? <code>gamepigeon auth login</code> signs in the same account.",
  });
}

/**
 * The `next` target was not a plain loopback URL, so we refuse to attach a
 * session token to it.
 */
export function invalidTargetPage(): string {
  return arcadePage({
    tone: "warn",
    title: "That sign-in link isn't valid",
    lead: "Tui only hands a session to a local listener on this machine, and this link points somewhere else.",
    steps: [
      "Close this tab and start sign-in from your terminal with <code>gamepigeon auth oauth google</code>.",
      "Use the link Tui printed rather than one that arrived from somewhere else.",
    ],
  });
}

/** The provider is not one we support (`google` / `github`). */
export function unknownProviderPage(): string {
  return arcadePage({
    tone: "warn",
    title: "That sign-in provider isn't supported",
    lead: "Tui signs in with Google or GitHub.",
    steps: [
      "Run <code>gamepigeon auth oauth google</code> or <code>gamepigeon auth oauth github</code>.",
    ],
    hint: "Prefer a password? <code>gamepigeon auth login</code> signs in the same account.",
  });
}

/** The provider is supported but has no credentials configured on this Worker. */
export function providerUnavailablePage(label: string): string {
  return arcadePage({
    tone: "warn",
    title: `${label} sign-in isn't set up`,
    lead: `This Tui deployment has no ${escapeHtml(label)} credentials configured, so it cannot start that sign-in.`,
    steps: [
      "Try the other provider, or ask whoever runs this deployment to add its client id and secret.",
    ],
    hint: "In the meantime, <code>gamepigeon auth signup</code> creates an account with an email and password.",
  });
}
