/**
 * Reads the session token out of a `Cookie` header, literally: the value we
 * forward is whatever the browser holds, not a field of whatever shape
 * `getSession` happens to return.
 */
export function sessionCookieToken(cookieHeader: string | null): string | null {
  if (!cookieHeader) return null;
  for (const pair of cookieHeader.split(";")) {
    const equals = pair.indexOf("=");
    if (equals === -1) continue;
    const name = pair.slice(0, equals).trim();
    if (name !== SESSION_COOKIE && name !== `__Secure-${SESSION_COOKIE}`) continue;
    const value = pair.slice(equals + 1).trim();
    if (value) return value;
  }
  return null;
}

/**
 * Starts a provider sign-in for the CLI. The provider round trip comes back to
 * `/cli/handoff`, which is what actually reaches the waiting listener; the CLI's
 * own address rides along as `next` so the handoff knows where that is.
 *
 * A cancelled or failed consent screen goes straight to the CLI listener with
 * `?error=...`, so the terminal says "cancelled" instead of waiting out its
 * timeout.
 */
export async function handleCliOAuth(request: Request, env: AuthEnv): Promise<Response> {
  const query = new URL(request.url).searchParams;

  const provider = query.get("provider");
  if (!isCliOAuthProvider(provider)) return htmlResponse(400, unknownProviderPage());
  if (!providerConfigured(env, provider)) {
    return htmlResponse(503, providerUnavailablePage(PROVIDER_LABELS[provider]));
  }

  const next = parseLoopbackTarget(query.get("next"));
  if (!next) return htmlResponse(400, invalidTargetPage());

  const handoff = new URL("/cli/handoff", env.BETTER_AUTH_URL);
  handoff.searchParams.set("next", next.toString());

  const { headers, response } = await createAuth(env).api.signInSocial({
    body: {
      provider,
      callbackURL: handoff.toString(),
      errorCallbackURL: next.toString(),
      disableRedirect: true,
    },
    headers: request.headers,
    returnHeaders: true,
  });

  const url = typeof response?.url === "string" ? response.url : null;
  if (!url) return htmlResponse(503, providerUnavailablePage(PROVIDER_LABELS[provider]));

  // The provider round trip needs the state cookie better-auth just issued.
  const redirect = new Headers();
  for (const cookie of headers.getSetCookie()) redirect.append("set-cookie", cookie);
  redirect.set("location", url);
  redirect.set("cache-control", "no-store");
  return new Response(null { status: 302, headers: redirect });
}

/**
 * Hands the signed-in browser session back to the CLI listener named by `next`,
 * keeping that URL's existing query (the CLI puts a `state` nonce there) and
 * appending the session token.
 */
export async function handleCliHandoff(request: Request, env: AuthEnv): Promise<Response> {
  // Validated before the session is touched: an untrusted target is a bad
  // request whether or not this browser happens to be signed in.
  const next = parseLoopbackTarget(new URL(request.url).searchParams.get("next"));
  if (!next) return htmlResponse(400, invalidTargetPage());

  const session = await createAuth(env).api.getSession({ headers: request.headers });
  const token = sessionCookieToken(request.headers.get("cookie"));
  if (!session?.user || !token) return htmlResponse(401, signInRequiredPage());

  next.searchParams.append("token", token);
  return htmlResponse(200, handoffPage(next.toString()));
}

