export interface AuthEnv {
  DB: D1Database;
  BETTER_AUTH_SECRET: string;
  MIGRATION_SECRET?: string;
  BETTER_AUTH_URL: string;
  PUBLIC_GAME_URL: string;
  BETTER_AUTH_TRUSTED_ORIGINS?: string;
  GOOGLE_CLIENT_ID?: string;
  GOOGLE_CLIENT_SECRET?: string;
  GITHUB_CLIENT_ID?: string;
  GITHUB_CLIENT_SECRET?: string;
}

// A CLI sign-in binds 3210 when it can and an OS-assigned port when it cannot
// (a second terminal, or the desktop overlay, already holds it), so loopback is
// trusted by pattern rather than by one port number. Every URL we actually hand
// a token to is re-checked in `cli-oauth.ts`.
const loopbackOriginPatterns = ["http://127.0.0.1:*", "http://localhost:*"];

export function trustedOrigins(env: AuthEnv): string[] {
  const configured = (env.BETTER_AUTH_TRUSTED_ORIGINS ?? "")
    .split(",")
    .map((value) => value.trim())
    .filter(Boolean);
  return [...new Set([
    ...configured,
    "http://127.0.0.1:3210",
    ...loopbackOriginPatterns,
    env.BETTER_AUTH_URL,
  ])];
}

/**
 * Only the providers with credentials in this environment are registered:
 * better-auth answers a sign-in for an unregistered provider with a generic
 * "provider not found", whereas `/cli/oauth` can say the deployment is missing
 * its client id and secret.
 */
function socialProviders(env: AuthEnv) {
  return {
    ...(env.GOOGLE_CLIENT_ID && env.GOOGLE_CLIENT_SECRET
      ? { google: { clientId: env.GOOGLE_CLIENT_ID, clientSecret: env.GOOGLE_CLIENT_SECRET } }
      : {}),
    ...(env.GITHUB_CLIENT_ID && env.GITHUB_CLIENT_SECRET
      ? { github: { clientId: env.GITHUB_CLIENT_ID, clientSecret: env.GITHUB_CLIENT_SECRET } }
      : {}),
  };
}

