test("the callback listener answers the readiness probe and rejects other paths", async () => {
  const callback = startOAuthCallbackServer(0);
  try {
    await callback.ready;
    const ping = await fetch(`http://127.0.0.1:${callback.port}/auth/ping`);
    expect(ping.status).toBe(200);
    expect(await ping.text()).toBe("ok");

    expect((await fetch(`http://127.0.0.1:${callback.port}/`)).status).toBe(404);
  } finally {
    callback.close();
  }
});

test("a token glued onto an existing state param still resolves", async () => {
  const callback = startOAuthCallbackServer(0);
  try {
    await callback.ready;
    // Some hosted redirects append `?token=...` to a callback that already
    // carried `?state=...`, so the pair arrives as `state=<nonce>?token=<value>`.
    const response = await fetch(
      `http://127.0.0.1:${callback.port}/auth/callback?state=nonce-1?token=session-secret`,
    );

    expect(response.status).toBe(200);
    expect(response.headers.get("cache-control")).toBe("no-store");
    expect(await response.text()).toContain("signed in");
    await expect(callback.token).resolves.toBe("session-secret");
  } finally {
    callback.close();
  }
});

test("a cancelled consent screen fails the attempt as cancelled", async () => {
  const callback = startOAuthCallbackServer(0);
  try {
    await callback.ready;
    const response = await fetch(
      `http://127.0.0.1:${callback.port}/auth/callback?state=nonce-1&error=access_denied`,
    );

    expect(response.status).toBe(400);
    expect(response.headers.get("cache-control")).toBe("no-store");
    expect(await response.text()).toMatch(/cancelled/i);
    await expect(callback.token).rejects.toThrow(/cancelled/i);
  } finally {
    callback.close();
  }
});

test("a reported error shows its description escaped and reports it raw", async () => {
  const callback = startOAuthCallbackServer(0);
  try {
    await callback.ready;
    const description = "<b>Google</b> said no";
    const response = await fetch(
      `http://127.0.0.1:${callback.port}/auth/callback?error=server_error`
        + `&error_description=${encodeURIComponent(description)}`,
    );

    expect(response.status).toBe(400);
    const body = await response.text();
    expect(body).toContain("&lt;b&gt;Google&lt;/b&gt; said no");
    expect(body).not.toContain("<b>Google</b>");
    await expect(callback.token).rejects.toThrow(description);
  } finally {
    callback.close();
  }
});

test("a missing token is reported instead of hanging", async () => {
