test("browser sign-in saves the session handed back to the listener", async () => {
  const testHome = mkdtempSync(join(tmpdir(), "gamepigeon-auth-"));
  process.env.HOME = testHome;
  process.env.GAMEPIGEON_AUTH_URL = "https://auth.example/";
  const lines: string[] = [];
  console.log = (...args: unknown[]) => void lines.push(args.map(String).join(" "));
  globalThis.fetch = Object.assign(
    async (input: RequestInfo | URL) => {
      expect(String(input)).toBe("https://auth.example/api/auth/get-session");
      return new Response(
        JSON.stringify({ user: { id: "usr_oauth", email: "person@example.com" } }),
        { status: 200 },
      );
    },
    { preconnect: fetch.preconnect },
  );

  try {
    const pending = runAuthCommand("oauth", "google");
    // The printed fallback link carries the callback the listener is bound to,
    // including the port it settled on.
    const printed = await Promise.race([
      (async () => {
        while (!lines.some((line) => line.includes("/cli/oauth"))) {
          await new Promise((resolve) => setTimeout(resolve, 5));
        }
        return lines.find((line) => line.includes("/cli/oauth")) ?? "";
      })(),
      pending.then(() => ""),
    ]);
    const started = new URL(printed.trim());
    expect(started.origin + started.pathname).toBe("https://auth.example/cli/oauth");
    expect(started.searchParams.get("provider")).toBe("google");

    const next = new URL(started.searchParams.get("next") ?? "");
    expect(next.protocol).toBe("http:");
    expect(next.hostname).toBe("127.0.0.1");
    expect(next.pathname).toBe("/auth/callback");
    expect(next.searchParams.get("state")).toMatch(/^[0-9a-f]{32}$/);

    next.searchParams.append("token", "session-secret");
    expect((await fetch(next.toString())).status).toBe(200);

    await expect(pending).resolves.toEqual({
      kind: "signed_in",
      method: "google",
      userId: "usr_oauth",
    });
    expect(readFileSync(join(testHome, ".tui-gamepigeon", "auth.json"), "utf8"))
      .toContain("session-secret");
  } finally {
    rmSync(testHome, { recursive: true, force: true });
  }
});

