    for (const provider of ["facebook", "apple", "", "google "]) {
      const response = await cliOAuth(
        `provider=${encodeURIComponent(provider)}&next=${encodeURIComponent(CLI_CALLBACK)}`,
      );
      expect(response.status).toBe(400);
    }
  });

  test("reports a provider with no credentials configured as unavailable", async () => {
    const response = await cliOAuth(
      `provider=github&next=${encodeURIComponent(CLI_CALLBACK)}`,
    );

    expect(response.status).toBe(503);
    expect(await response.text()).toMatch(/no GitHub credentials configured/i);
  });

  test("refuses a next target that is not a loopback URL", async () => {
    const response = await cliOAuth(
      `provider=google&next=${encodeURIComponent("https://evil.example/steal")}`,
    );

    expect(response.status).toBe(400);
    expect(await response.text()).not.toContain("evil.example");
  });

  test("refuses a missing next target", async () => {
    expect((await cliOAuth("provider=google")).status).toBe(400);
  });

  test("sends the browser to the provider, coming back through the handoff", async () => {
    const response = await cliOAuth(
      `provider=google&next=${encodeURIComponent(CLI_CALLBACK)}`,
    );

    expect(response.status).toBe(302);
    const location = new URL(response.headers.get("location") ?? "");
    expect(location.hostname).toBe("accounts.google.com");
    expect(location.searchParams.get("client_id")).toBe("test-google-client");

    // The provider returns to the Worker, which then hands off to the CLI.
    const providerCallback = new URL(location.searchParams.get("redirect_uri") ?? "");
    expect(providerCallback.toString())
      .toBe("https://auth.runretroarcade.com/api/auth/callback/google");
    // The state cookie better-auth just issued has to reach the browser, or the
    // round trip cannot be verified when it comes back.
    expect(response.headers.getSetCookie().join("\n")).toMatch(/oauth_state=/);
    expect(response.headers.get("cache-control")).toBe("no-store");
  });
});

