import { env } from "cloudflare:workers";
import { getMigrations } from "better-auth/db/migration";
import { beforeAll, describe, expect, test } from "vitest";
import { createAuth, type AuthEnv } from "../src/auth";
import { handoffPage } from "../src/handoff-page";
import worker from "../src/index";
import { parseLoopbackTarget, sessionCookieToken } from "../src/cli-oauth";

// Only the CLI listener may receive a session token, so `/cli/oauth` and
// `/cli/handoff` are configured with credentials that never leave this test.
const configured: AuthEnv = {
  ...env,
  GOOGLE_CLIENT_ID: "test-google-client",
  GOOGLE_CLIENT_SECRET: "test-google-secret",
};

const CLI_CALLBACK = "http://127.0.0.1:3210/auth/callback?state=nonce-1";

function get(path: string, init: RequestInit = {}, workerEnv: AuthEnv = env): Promise<Response> {
  return worker.fetch(new Request(`https://auth.runretroarcade.com${path}`, init), workerEnv);
}

function cliOAuth(query: string, workerEnv: AuthEnv = configured): Promise<Response> {
  return get(`/cli/oauth?${query}`, {}, workerEnv);
}

function cliHandoff(next: string, init: RequestInit = {}): Promise<Response> {
  return get(`/cli/handoff?next=${encodeURIComponent(next)}`, init);
}

describe("loopback target validation", () => {
  test.each([
    "http://127.0.0.1:3210/auth/callback",
    "http://127.0.0.1:54321/auth/callback?state=nonce-1",
    "http://localhost:3210/auth/callback",
  ])("accepts %s", (value) => {
    expect(parseLoopbackTarget(value)?.toString()).toBe(new URL(value).toString());
  });

  test.each([
    // Not loopback at all.
    "https://runretroarcade.com/auth/callback",
    "http://runretroarcade.com/auth/callback",
    // https on loopback is not what the CLI listener serves.
    "https://127.0.0.1:3210/auth/callback",
    // Authority and scheme tricks that read as loopback at a glance.
    "http://127.0.0.1@evil.example/auth/callback",
    "http://localhost.evil.example/auth/callback",
    "http://127.0.0.1.evil.example/auth/callback",
    "javascript:alert(1)//127.0.0.1",
    "//127.0.0.1:3210/auth/callback",
    "/auth/callback",
    "",
  ])("rejects %s", (value) => {
    expect(parseLoopbackTarget(value)).toBeNull();
  });

  test("rejects a missing target", () => {
    expect(parseLoopbackTarget(null)).toBeNull();
  });
});

describe("session cookie reading", () => {
  test("reads the better-auth session cookie, including its secure spelling", () => {
    expect(sessionCookieToken("better-auth.session_token=abc.def")).toBe("abc.def");
    expect(sessionCookieToken("other=1; __Secure-better-auth.session_token=abc.def; x=2"))
      .toBe("abc.def");
  });

  test("ignores everything else", () => {
    expect(sessionCookieToken(null)).toBeNull();
    expect(sessionCookieToken("better-auth.session_data=cached")).toBeNull();
    expect(sessionCookieToken("better-auth.session_token=")).toBeNull();
  });
});

