 * URL on this machine. `URL` parsing does the load-bearing work: an authority
 * trick like `http://127.0.0.1@evil.example/` has hostname `evil.example`, and
 * `https://localhost.evil.example` fails on both checks.
 */
export function parseLoopbackTarget(value: string | null): URL | null {
  if (!value) return null;
  let target: URL;
  try {
    target = new URL(value);
  } catch {
    return null;
  }
  if (target.protocol !== "http:") return null;
  if (!LOOPBACK_HOSTNAMES.has(target.hostname)) return null;
