    // round trip cannot be verified when it comes back.
    expect(response.headers.getSetCookie().join("\n")).toMatch(/oauth_state=/);
    expect(response.headers.get("cache-control")).toBe("no-store");
  });
});

describe("GET /cli/handoff", () => {
