  test("reports a provider with no credentials configured as unavailable", async () => {
    const response = await cliOAuth(
      `provider=github&next=${encodeURIComponent(CLI_CALLBACK)}`,
    );

    expect(response.status).toBe(503);
    expect(await response.text()).toMatch(/no GitHub credentials configured/i);
  });

  test("refuses a next target that is not a loopback URL", async () => {
    const response = await cliOAuth(
      `provider=google&next=${encodeURIComponent("https://evil.example/steal")}`,
    );

    expect(response.status).toBe(400);
    expect(await response.text()).not.toContain("evil.example");
  });

  test("refuses a missing next target", async () => {
    expect((await cliOAuth("provider=google")).status).toBe(400);
  });

  test("sends the browser to the provider, coming back through the handoff", async () => {
    const response = await cliOAuth(
      `provider=google&next=${encodeURIComponent(CLI_CALLBACK)}`,
    );

    expect(response.status).toBe(302);
    const location = new URL(response.headers.get("location") ?? "");
    expect(location.hostname).toBe("accounts.google.com");
    expect(location.searchParams.get("client_id")).toBe("test-google-client");

    // The provider returns to the Worker, which then hands off to the CLI.
    const providerCallback = new URL(location.searchParams.get("redirect_uri") ?? "");
    expect(providerCallback.toString())
      .toBe("https://auth.runretroarcade.com/api/auth/callback/google");
    // The state cookie better-auth just issued has to reach the browser, or the
    // round trip cannot be verified when it comes back.
    expect(response.headers.getSetCookie().join("\n")).toMatch(/oauth_state=/);
    expect(response.headers.get("cache-control")).toBe("no-store");
  });
});

describe("GET /cli/handoff", () => {
  test("refuses a next target that is not a loopback URL, before any session work", async () => {
    for (const next of ["https://evil.example/steal", "http://evil.example/steal"]) {
      const response = await cliHandoff(next, {
        headers: { cookie: "__Secure-better-auth.session_token=stolen.signature" },
      });
      expect(response.status).toBe(400);
      expect(await response.text()).not.toContain("stolen.signature");
    }
  });

  test("answers an unauthenticated browser with the command to run", async () => {
    const response = await cliHandoff(CLI_CALLBACK);

    expect(response.status).toBe(401);
    expect(await response.text()).toMatch(/oauth/i);
  });

  test("does not trust a session cookie that resolves to no user", async () => {
    const response = await cliHandoff(CLI_CALLBACK, {
      headers: { cookie: "better-auth.session_token=not-a-real.token" },
    });

    expect(response.status).toBe(401);
  });
});

describe("GET /cli/handoff with a signed-in browser", () => {
  let cookie = "";

  beforeAll(async () => {
    const auth = createAuth(env);
    const { toBeCreated, toBeAdded, runMigrations } = await getMigrations(auth.options);
    if (toBeCreated.length > 0 || toBeAdded.length > 0) await runMigrations();

    const { headers } = await auth.api.signUpEmail({
      body: { email: "handoff@example.com", password: "correct horse battery", name: "Handoff" },
      returnHeaders: true,
    });
    const sessionCookie = headers.getSetCookie()
      .map((value) => value.split(";")[0] ?? "")
      .find((value) => value.includes("better-auth.session_token="));
    cookie = sessionCookie ?? "";
    expect(cookie).not.toBe("");
  });

  test("redirects to the CLI listener with the session token appended", async () => {
    const response = await cliHandoff(CLI_CALLBACK, { headers: { cookie } });

    expect(response.status).toBe(200);
    expect(response.headers.get("cache-control")).toBe("no-store");

    const token = sessionCookieToken(cookie) ?? "";
    // The CLI reads this value straight out of the query without decoding it, so
    // it has to survive the URL round trip untouched.
    expect(token).toMatch(/^[A-Za-z0-9._~-]+$/);
    const expected = new URL(CLI_CALLBACK);
    expected.searchParams.append("token", token);

    const body = await response.text();
    // The literal target, un-escaped, is what the scripted redirect uses.
    expect(body).toContain(expected.toString());
    // The state the CLI put on its callback survives the round trip.
    expect(expected.searchParams.get("state")).toBe("nonce-1");
    expect(expected.searchParams.get("token")).toBe(token);
  });

  test("keeps refusing a non-loopback target for a signed-in browser", async () => {
    const response = await cliHandoff("https://evil.example/steal", { headers: { cookie } });

    expect(response.status).toBe(400);
  });
});

describe("handoff page", () => {
  test("redirects by script and by meta refresh, escaping only the markup copy", () => {
    const url = "http://127.0.0.1:3210/auth/callback?state=nonce-1&token=abc.def";
    const page = handoffPage(url);

    expect(page).toContain(`location.replace("${url}")`);
    expect(page).toContain(
      '<meta http-equiv="refresh" content="0;url=http://127.0.0.1:3210/auth/callback?state=nonce-1&amp;token=abc.def">',
    );
  });
});

