       if (!value) return null;
       let target: URL; try { target = new URL(value); } catch { return null; }
       if (target.protocol !== "http:") return null;
       if (!LOOPBACK_HOSTNAMES.has(target.hostname)) return null;
       return target;
     }
     export function sessionCookieToken(cookieHeader: string | null): string | null { /* literal read of
       better-auth.session_token or __Secure-better-auth.session_token */ }
     export async function handleCliOAuth(request, env) {
       provider not google/github → 400 unknownProviderPage();
       !providerConfigured → 503 providerUnavailablePage(label);
       !parseLoopbackTarget(next) → 400 invalidTargetPage();
       handoff = new URL("/cli/handoff", env.BETTER_AUTH_URL); handoff.searchParams.set("next", next.toString());
       try { started = await createAuth(env).api.signInSocial({ body: { provider,
         callbackURL: handoff.toString(), errorCallbackURL: next.toString(), disableRedirect: true },
         headers: request.headers, returnHeaders: true }); }
       catch { return htmlResponse(503, signInUnavailablePage()); }
       !url → 503 signInUnavailablePage();
       302 with getSetCookie() forwarded (oauth_state), location, cache-control: no-store;
     }
     export async function handleCliHandoff(request, env) {
       next validated first → 400;
       session = await createAuth(env).api.getSession({ headers: request.headers });
       token = sessionCookieToken(request.headers.get("cookie"));
       if (!session?.user || !token) return htmlResponse(401, signInRequiredPage());
       // raw query append — NOT searchParams (avoids double-encoding %)
       next.search = next.search ? `${next.search}&token=${token}` : `?token=${token}`;
       return htmlResponse(200, handoffPage(next.toString()));
     }
